    <aside className=\"sidebar\">
      <a href=\"#\" className=\"brand\" onClick={e => { e.preventDefault(); switchSection('Клиенты'); }}><span className=\"brand-symbol\"><span/><span/><span/><span/></span>контур<span className=\"brand-period\">.</span></a>
      <button className=\"workspace\" onClick={() => setModal('settings')}><span className=\"workspace-icon\">М</span><span><strong>{workspaceName}</strong><small>Рабочее пространство</small></span><Icon name=\"chevron\" size={14} className=\"down\"/></button>
      <div className=\"nav-label\">РАБОЧЕЕ ПРОСТРАНСТВО</div>
      <nav>{([{ name: 'Обзор', icon: 'grid' }, { name: 'Клиенты', icon: 'users' }, { name: 'Компании', icon: 'building' }, { name: 'Архив', icon: 'archive' }] as { name: string; icon: IconName }[]).map(item => <button key={item.name} className={"'`nav-item ${section === item.name ? '"'active' : ''}"'`} onClick={() => switchSection(item.name)}><Icon name={item.icon} size={19}/><span>{item.name}</span>{item.name === '"'Клиенты' && <span className=\"nav-count\">{clients.length}</span>}</button>)}</nav>
      <div className=\"sidebar-bottom\"><div className=\"team-card\"><span className=\"team-spark\"><Icon name=\"spark\" size={18}/></span><strong>Всё начинается с людей</strong><p>Соберите клиентов и важные<br/>контакты в одном месте.</p><button onClick={openAdd}>Добавить клиента <Icon name=\"plus\" size={15}/></button></div><button className=\"nav-item muted\" onClick={() => setModal('help')}><Icon name=\"help\" size={19}/>Помощь и поддержка<Icon name=\"chevron\" size={14}/></button><button className=\"nav-item muted\" onClick={() => setModal('settings')}><Icon name=\"settings\" size={19}/>Настройки</button><div className=\"profile\"><span className=\"profile-avatar\">АС</span><span><strong>Алексей Соколов</strong><small>Личный аккаунт</small></span><button aria-label=\"Настройки аккаунта\" onClick={() => setModal('settings')}><Icon name=\"chevron\" size={16}/></button></div></div>
    </aside>
    <div className=\"main-shell\"><header className=\"topbar\"><div className=\"breadcrumbs\"><Icon name=\"grid\" size={17}/><span>Рабочее пространство</span><Icon name=\"chevron\" size={13}/><strong>{section}</strong></div><div className=\"header-right\"><span className=\"live-dot\"/>Все изменения сохранены<span className=\"top-divider\"/><button className=\"icon-button\" aria-label=\"Справка\" onClick={() => setModal('help')}><Icon name=\"help\" size={19}/></button><span className=\"mini-avatar\">АС</span></div></header>
      <main><div className=\"page-heading\"><div><div className=\"eyebrow\">ВАШИ КОНТАКТЫ. НОВЫЕ ВОЗМОЖНОСТИ.</div><h1>{section}</h1><p>{section === 'Компании' ? 'Компании, с которыми вы строите долгосрочные отношения.' : section === 'Обзор' ? 'Всё, что важно знать о вашей клиентской базе.' : section === 'Архив' ? 'Архивные контакты — всегда под рукой.' : 'Управляйте клиентами и развивайте отношения в одном месте.'}</p></div><div className=\"heading-actions\"><button className=\"button\" onClick={exportCsv}><Icon name=\"download\" size={17}/>Экспорт</button><button className=\"button primary\" onClick={openAdd}><Icon name=\"plus\" size={18}/>Добавить клиента</button></div></div>
      <div className=\"stats-grid\">
        {[{ label: 'Всего клиентов', value: clients.length, icon: 'users', note: 'В вашей клиентской базе', cls: 'purple' }, { label: 'Активные клиенты', value: counts.active, icon: 'check', note: "'`${Math.round(counts.active / (clients.length || 1) * 100)}% от общего числа`, cls: '"'green' }, { label: 'Новые клиенты', value: counts.new, icon: 'spark', note: 'Готовы к знакомству', cls: 'blue' }, { label: 'Сумма сделок', value: money(clients.reduce((sum, c) => sum + c.amount, 0)), icon: 'building', note: 'За всё время', cls: 'orange' }].map((stat, i) => <div className=\"stat-card\" key={stat.label}><div className=\"stat-top\"><span>{stat.label}</span><span className={"'`stat-icon ${stat.cls}`}><Icon name={stat.icon as IconName} size={17}/></span></div><div className={`stat-value ${i === 3 ? '"'money-stat' : ''}"'`}>{stat.value}<span className="stat-dash">{i === 0 && <span className="stat-count">+{counts.new} новых</span>}</span></div><div className="stat-note">{stat.note}</div></div>)}
      </div>
      {section === '"'Компании' ? <section className=\"company-grid\">{Array.from(new Set(clients.map(c => c.company))).map((company, i) => { const members = clients.filter(c => c.company === company); return <button className=\"company-card\" key={company} onClick={() => { switchSection('Клиенты'); setQuery(company); }}><span className={"'`avatar color-${i % 8}`}><Icon name="building"/></span><h3>{company}</h3><p>Контактов: {members.length}</p><strong>{money(members.reduce((sum, c) => sum + c.amount, 0))}</strong><span className="company-link">Посмотреть клиентов <Icon name="chevron" size={14}/></span></button>; })}</section> : <section className="table-card">
        <div className="tabs" role="tablist" aria-label="Категории клиентов">{[['"'Все клиенты', clients.length], ['Активные', counts.active], ['Новые', counts.new], ['Архив', counts.archive]].map(([label, count]) => <button role=\"tab\" aria-selected={tab === label} key={label} className={"'`tab ${tab === label ? '"'chosen' : ''}"'`} onClick={() => setTab(String(label))}>{label}<span>{count}</span></button>)}<span className="table-records">Клиентская база</span></div>
        <div className="table-toolbar"><div className="search-box"><Icon name="search" size={18}/><input ref={searchRef} value={query} onChange={e => setQuery(e.target.value)} placeholder="Поиск по имени, почте или компании" aria-label="Поиск клиентов"/>{query ? <button onClick={() => setQuery('"'')} aria-label=\"Очистить поиск\"><Icon name=\"close\" size={15}/></button> : <kbd>⌘ K</kbd>}</div><div className=\"toolbar-buttons\"><div className=\"popover-wrapper\"><button className={"'`button ${filter !== '"'Все статусы' ? 'filter-active' : ''}"'`} onClick={() => setPopover(popover === '"'filter' ? null : 'filter')}><Icon name=\"filter\" size={17}/>Фильтры{filter "'!== '"'Все статусы' && <span className=\"filter-dot\"/>}</button>{popover === 'filter' && <div className=\"dropdown filter-dropdown\"><strong>Статус клиента</strong>{['Все статусы', 'Активный', 'Новый', 'В архиве'].map(s => <button key={s} className={s === filter ? 'selected-option' : ''} onClick={() => { setFilter(s); setPopover(null); }}>{s}{s === filter && <Icon name=\"check\" size={15}/>}</button>)}</div>}</div><div className=\"popover-wrapper\"><button className=\"button\" onClick={() => setPopover(popover === 'columns' ? null : 'columns')}><Icon name=\"columns\" size={17}/>Столбцы</button>{popover === 'columns' && <div className=\"dropdown columns-dropdown\"><strong>Отображаемые столбцы</strong>{columnDefs.map(col => <label key={col.key}><input type=\"checkbox\" className=\"checkbox\" checked={"'!hidden.has(col.key)} disabled={col.key === '"'name'} onChange={() => setHidden(prev => { const next = new Set(prev); next.has(col.key) ? next.delete(col.key) : next.add(col.key); return next; })}/>{col.label}</label>)}</div>}</div></div></div>
        {(selected.size > 0 || filter "'!== '"'Все статусы') && <div className=\"selection-toolbar\">{selected.size > 0 ? <><span><strong>Выбрано: {selected.size}</strong></span><button onClick={exportCsv}><Icon name=\"download\" size={15}/>Экспортировать</button><button onClick={() => { setClients(prev => prev.map(c => selected.has(c.id) ? { ...c, status: 'В архиве' } : c)); setSelected(new Set()); setToast('Выбранные клиенты перемещены в архив'); }}><Icon name=\"archive\" size={15}/>В архив</button><button className=\"clear-selection\" onClick={() => setSelected(new Set())}>Снять выделение<Icon name=\"close\" size={14}/></button></> : <><span>Статус: {filter}</span><button onClick={() => setFilter('Все статусы')}>Сбросить<Icon name=\"close\" size={14}/></button></>}</div>}
        <div className=\"table-scroll\"><table><thead><tr><th className=\"checkbox-cell\"><Checkbox checked={allChecked} mixed={"'!allChecked && someChecked} onChange={togglePage} label="Выбрать все строки на странице"/></th>{columnDefs.filter(c => !hidden.has(c.key)).map(col => <th key={col.key} className={col.key === '"'amount' ? 'amount-column' : ''} aria-sort={sort.key === col.key ? sort.asc ? 'ascending' : 'descending' : 'none'}><button className={"'`sort-button ${sort.key === col.key ? '"'sorted' : ''}"'`} onClick={() => setSort({ key: col.key, asc: sort.key === col.key ? !sort.asc : true })}>{col.label}{sort.key === col.key ? <span className="sort-direction">{sort.asc ? '"'↑' : '↓'}</span> : <Icon name=\"arrow\" size={12}/>}</button></th>)}<th className=\"actions-cell\"><span className=\"sr-only\">Действия</span></th></tr></thead><tbody>{rows.map(client => <tr key={client.id} className={selected.has(client.id) ? 'selected-row' : ''}><td className=\"checkbox-cell\"><Checkbox checked={selected.has(client.id)} onChange={() => toggleSelection(client.id)} label={"'`Выбрать: ${client.name}`}/></td><td><button className="client-info" onClick={() => setDetail(client)}><span className={`avatar color-${client.color}`}>{initials(client.name)}</span><span><strong>{client.name}</strong><small>{client.email}</small></span></button></td>{!hidden.has('"'company') && <td><div className=\"company-info\"><strong>{client.company}</strong><small>{client.role}</small></div></td>}{"'!hidden.has('"'status') && <td><span className={"'`status-badge ${client.status === '"'Активный' ? 'status-active' : client.status === 'Новый' ? 'status-new' : 'status-archived'}"'`}><span/>{client.status}</span></td>}{!hidden.has('"'date') && <td className=\"date-cell\">{shortDate(client.date)}</td>}{"'!hidden.has('"'amount') && <td className=\"amount-cell\">{money(client.amount)}</td>}<td className=\"actions-cell\"><div className=\"popover-wrapper\"><button className={"'`icon-button row-more ${popover === '"'row-' + client.id ? 'pressed' : ''}"'`} aria-label={`Действия: ${client.name}`} onClick={() => setPopover(popover === '"'row-' + client.id ? null : 'row-' + client.id)}><Icon name=\"more\" size={19}/></button>{popover === 'row-' + client.id && <div className=\"dropdown row-dropdown\"><button onClick={() => { setDetail(client); setPopover(null); }}>Открыть карточку</button><button onClick={() => { setEditing(client); setModal('add'); setPopover(null); }}>Редактировать</button><button onClick={() => setStatus(client.id, client.status === 'В архиве' ? 'Активный' : 'В архиве')}>{client.status === 'В архиве' ? 'Восстановить' : 'Переместить в архив'}</button></div>}</div></td></tr>)}</tbody></table>{rows.length === 0 && <div className=\"empty-state\"><Icon name=\"search\" size={32}/><h3>Клиенты не найдены</h3><p>Попробуйте изменить запрос или сбросить фильтры.</p><button className=\"button\" onClick={() => { setQuery(''); setFilter('Все статусы'); setTab('Все клиенты'); }}>Сбросить фильтры</button></div>}</div>
        <div className=\"pagination\"><span className=\"results-count\">Показано <strong>{filtered.length ? (currentPage - 1) * pageSize + 1 : 0}–{Math.min(currentPage * pageSize, filtered.length)}</strong> из <strong>{filtered.length}</strong> клиентов</span><div className=\"pagination-right\"><label className=\"page-size\">Строк на странице<select aria-label=\"Строк на странице\" value={pageSize} onChange={e => setPageSize(Number(e.target.value))}><option>8</option><option>16</option><option>24</option></select></label><div className=\"page-buttons\"><button aria-label=\"Предыдущая страница\" disabled={currentPage === 1} onClick={() => setPage(currentPage - 1)}><Icon name=\"chevron\" className=\"rotate\" size={16}/></button>{Array.from({ length: pageCount }, (_, i) => <button key={i} aria-label={"'`Страница ${i + 1}`} aria-current={currentPage === i + 1 ? '"'page' : undefined} className={currentPage === i + 1 ? 'current-page' : ''} onClick={() => setPage(i + 1)}>{i + 1}</button>)}<button aria-label=\"Следующая страница\" disabled={currentPage === pageCount} onClick={() => setPage(currentPage + 1)}><Icon name=\"chevron\" size={16}/></button></div></div></div>
      </section>}
      <div className=\"page-footer\"><span><Icon name=\"help\" size={14}/>Нажмите на заголовок столбца, чтобы изменить сортировку</span><span>Порядок в контактах. Простор для роста.</span></div>
      </main>
    </div>
    {popover && <div className=\"popover-backdrop\" onClick={() => setPopover(null)}/>}
    {(modal || detail) && <div className=\"modal-backdrop\" onClick={() => { setModal(null); setDetail(null); }}><div className=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-label={detail ? 'Карточка клиента' : modal === 'add' ? 'Данные клиента' : modal === 'help' ? 'Помощь' : 'Настройки'} onClick={e => e.stopPropagation()}><button className=\"modal-close icon-button\" aria-label=\"Закрыть\" onClick={() => { setModal(null); setDetail(null); }}><Icon name=\"close\"/></button>
      {modal === 'add' ? <><span className=\"modal-icon\"><Icon name=\"users\" size={24}/></span><h2>{editing ? 'Редактировать клиента' : 'Новый клиент'}</h2><p>Каждое знакомство — начало новых возможностей.</p><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); const entry: Client = { id: editing?.id ?? Date.now(), name: String(f.get('name')).trim(), email: String(f.get('email')).trim(), company: String(f.get('company')).trim(), role: String(f.get('role')).trim(), status: f.get('status') as Status, date: editing?.date ?? new Date().toISOString().slice(0, 10), amount: Number(f.get('amount')), color: editing?.color ?? clients.length % 8 }; if ("'!entry.name || !entry.company) return; setClients(prev => editing ? prev.map(c => c.id === editing.id ? entry : c) : [entry, ...prev]); setModal(null); setToast(editing ? '"'Данные клиента сохранены' : 'Клиент добавлен'); if ("'!editing) { switchSection('"'Клиенты'); setSort({ key: 'date', asc: false }); setPage(1); } }}><label>Имя и фамилия<input name=\"name\" autoFocus required maxLength={80} defaultValue={editing?.name} placeholder=\"Например, Иван Петров\"/></label><label>Электронная почта<input name=\"email\" type=\"email\" required defaultValue={editing?.email} placeholder=\"ivan@company.ru\"/></label><div className=\"form-columns\"><label>Компания<input name=\"company\" required maxLength={80} defaultValue={editing?.company} placeholder=\"Название компании\"/></label><label>Должность<input name=\"role\" maxLength={80} defaultValue={editing?.role} placeholder=\"Менеджер\"/></label></div><div className=\"form-columns\"><label>Статус<select name=\"status\" defaultValue={editing?.status ?? 'Новый'}><option>Новый</option><option>Активный</option><option>В архиве</option></select></label><label>Сумма сделок, ₽<input name=\"amount\" type=\"number\" min=\"0\" max=\"999999999999\" step=\"0.01\" defaultValue={editing?.amount ?? 0} required/></label></div><div className=\"modal-actions\"><button type=\"button\" className=\"button\" onClick={() => setModal(null)}>Отмена</button><button type=\"submit\" className=\"button primary\">{editing ? 'Сохранить изменения' : 'Добавить клиента'}</button></div></form></> : modal === 'help' ? <><span className=\"modal-icon\"><Icon name=\"help\" size={24}/></span><h2>Всё под рукой</h2><p>Небольшая памятка по работе с клиентами.</p><div className=\"help-list\"><div><Icon name=\"arrow\"/><span><strong>Сортируйте по любому столбцу</strong><p>Повторное нажатие меняет порядок сортировки.</p></span></div><div><Icon name=\"check\"/><span><strong>Выбирайте и действуйте</strong><p>Чекбокс в заголовке выбирает текущую страницу. Выбор сохраняется при переходе между страницами.</p></span></div><div><Icon name=\"search\"/><span><strong>Находите нужные контакты</strong><p>Ищите по имени, почте или компании. Используйте ⌘ K или Ctrl K для быстрого поиска.</p></span></div><div><Icon name=\"download\"/><span><strong>Скачивайте данные</strong><p>Экспорт сохраняет выбранные строки или все отфильтрованные записи в CSV.</p></span></div></div></> : modal === 'settings' ? <><span className=\"modal-icon\"><Icon name=\"settings\" size={24}/></span><h2>Рабочее пространство</h2><p>Настройте пространство для вашей команды.</p><form onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); setWorkspaceName(String(f.get('workspace')).trim() || 'Моя команда'); setModal(null); setToast('Настройки сохранены'); }}><label>Название команды<input autoFocus name=\"workspace\" required maxLength={28} defaultValue={workspaceName}/></label><label>Строк на странице по умолчанию<select value={pageSize} onChange={e => setPageSize(Number(e.target.value))}><option>8</option><option>16</option><option>24</option></select></label><div className=\"modal-actions\"><button type=\"submit\" className=\"button primary\">Сохранить</button></div></form></> : detail && <><span className={"'`avatar detail-avatar color-${detail.color}`}>{initials(detail.name)}</span><h2>{detail.name}</h2><p>{detail.role} · {detail.company}</p><dl className="detail-list"><div><dt>Электронная почта</dt><dd><a href={`mailto:${detail.email}`}>{detail.email}</a></dd></div><div><dt>Статус</dt><dd>{detail.status}</dd></div><div><dt>Дата добавления</dt><dd>{shortDate(detail.date)}</dd></div><div><dt>Сумма сделок</dt><dd>{money(detail.amount)}</dd></div></dl><div className="modal-actions"><button className="button" onClick={() => setStatus(detail.id, detail.status === '"'В архиве' ? 'Активный' : 'В архиве')}>{detail.status === 'В архиве' ? 'Восстановить' : 'В архив'}</button><button className=\"button primary\" onClick={() => { setEditing(detail); setDetail(null); setModal('add'); }}>Редактировать</button></div></>}
    </div></div>}
    {toast && <div className=\"toast\" role=\"status\"><span><Icon name=\"check\" size={17}/></span>{toast}<button aria-label=\"Закрыть уведомление\" onClick={() => setToast('')}><Icon name=\"close\" size={16}/></button></div>}
  </div>;
}
EOF
