    grid: <><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/></>,
    users: <><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></>,
    building: <><rect x=\"5\" y=\"3\" width=\"14\" height=\"18\" rx=\"2\"/><path d=\"M9 7h1m4 0h1M9 11h1m4 0h1M9 15h1m4 0h1m-4 6v-3h2v3\"/></>,
    chevron: <path d=\"m9 5 7 7-7 7\"/>, plus: <path d=\"M12 5v14M5 12h14\"/>,
    search: <><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 4.5 4.5\"/></>,
    filter: <><path d=\"M4 7h16M4 17h16\"/><rect x=\"7\" y=\"4\" width=\"4\" height=\"6\" rx=\"1\" fill=\"currentColor\" stroke=\"none\"/><rect x=\"14\" y=\"14\" width=\"4\" height=\"6\" rx=\"1\" fill=\"currentColor\" stroke=\"none\"/></>,
    columns: <><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M9 4v16m6-16v16\"/></>,
    download: <><path d=\"M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4\"/></>,
    arrow: <><path d=\"M8 19V5m-4 4 4-4 4 4m4-4v14m-4-4 4 4 4-4\"/></>,
    more: <><circle cx=\"5\" cy=\"12\" r=\"1\"/><circle cx=\"12\" cy=\"12\" r=\"1\"/><circle cx=\"19\" cy=\"12\" r=\"1\"/></>,
    close: <path d=\"m6 6 12 12M6 18 18 6\"/>, check: <path d=\"m5 12 4 4L19 6\"/>,
    help: <><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M9.5 9a2.5 2.5 0 1 1 4 2c-1.5 1-1.5 1.5-1.5 2.5M12 17h.01\"/></>,
    settings: <><path d=\"m10 3-1 3-3 1-3 3 2 2-1 4 4 1 2 4 3-2 4 1 1-4 3-2-2-3 1-4-4-1-2-3Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></>,
    logout: <><path d=\"M10 4H4v16h6m5-12 4 4-4 4m-7-4h11\"/></>,
    mail: <><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"m3 6 9 7 9-7\"/></>,
    archive: <><rect x=\"3\" y=\"3\" width=\"18\" height=\"5\" rx=\"1\"/><path d=\"M5 8v13h14V8m-10 4h6\"/></>,
    spark: <><path d=\"m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8Z\"/></>,
    clock: <><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></>,
  };
  return <svg width={size} height={size} viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.65\" strokeLinecap=\"round\" strokeLinejoin=\"round\" {...props}>{paths[name]}</svg>;
}

