const initialClients: Client[] = seed.map((r, i) => ({ id: i + 1, name: String(r[0]), email: String(r[1]), company: String(r[2]), role: String(r[3]), status: r[4] as Status, date: String(r[5]), amount: Number(r[6]), color: i % 8 }));
