const columnDefs = [{ key: 'name', label: 'Клиент' }, { key: 'company', label: 'Компания' }, { key: 'status', label: 'Статус' }, { key: 'date', label: 'Дата добавления' }, { key: 'amount', label: 'Сумма сделок' }] as const;
type SortKey = typeof columnDefs[number]['key'];
function Checkbox({ checked, mixed, onChange, label }: { checked: boolean; mixed?: boolean; onChange: () => void; label: string }) {
  const ref = useRef<HTMLInputElement>(null);
  useEffect(() => { if (ref.current) ref.current.indeterminate = "'!!mixed; }, [mixed]);
  return <input ref={ref} type="checkbox" className="checkbox" checked={checked} onChange={onChange} aria-label={label} />;
}

export function App() {
  const [clients, setClients] = useState(initialClients);
  const [query, setQuery] = useState('"'');
  const [tab, setTab] = useState('Все клиенты');
  const [filter, setFilter] = useState('Все статусы');
  const [sort, setSort] = useState<{ key: SortKey; asc: boolean }>({ key: 'date', asc: false });
  const [selected, setSelected] = useState<Set<number>>(new Set());
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(8);
  const [hidden, setHidden] = useState<Set<string>>(new Set());
