  const [modal, setModal] = useState<'add' | 'help' | 'settings' | null>(null);
  const [detail, setDetail] = useState<Client | null>(null);
  const [toast, setToast] = useState('');
  const [section, setSection] = useState('Клиенты');
  const [workspaceName, setWorkspaceName] = useState('Моя команда');
  const [editing, setEditing] = useState<Client | null>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const counts = { active: clients.filter(c => c.status === 'Активный').length, new: clients.filter(c => c.status === 'Новый').length, archive: clients.filter(c => c.status === 'В архиве').length };
  const filtered = useMemo(() => clients.filter(c => {
    const matchesTab = tab === 'Все клиенты' || (tab === 'Активные' && c.status === 'Активный') || (tab === 'Новые' && c.status === 'Новый') || (tab === 'Архив' && c.status === 'В архиве');
    return matchesTab && (filter === 'Все статусы' || c.status === filter) && "'`${c.name} ${c.email} ${c.company} ${c.role}`.toLowerCase().includes(query.toLowerCase());
  }).sort((a, b) => { const x = a[sort.key], y = b[sort.key]; return (typeof x === '"'number' && typeof y === 'number' ? x - y : String(x).localeCompare(String(y), 'ru')) * (sort.asc ? 1 : -1); }), [clients, query, filter, tab, sort]);
  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  const rows = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  const allChecked = rows.length > 0 && rows.every(c => selected.has(c.id));
  const someChecked = rows.some(c => selected.has(c.id));
  useEffect(() => { setPage(1); }, [query, filter, tab, pageSize]);
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(''), 4000); return () => clearTimeout(t); } }, [toast]);
  useEffect(() => { const key = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); searchRef.current?.focus(); } if (e.key === 'Escape') { setPopover(null); setModal(null); setDetail(null); } }; window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key); }, []);
  const toggleSelection = (id: number) => setSelected(prev => { const next = new Set(prev); next.has(id) ? next.delete(id) : next.add(id); return next; });
  const togglePage = () => setSelected(prev => { const next = new Set(prev); rows.forEach(c => allChecked ? next.delete(c.id) : next.add(c.id)); return next; });
  const exportCsv = () => {
    const exportRows = selected.size ? clients.filter(c => selected.has(c.id)) : filtered;
    const csv = '\\uFEFF' + [['Имя', 'Email', 'Компания', 'Должность', 'Статус', 'Дата', 'Сумма'], ...exportRows.map(c => [c.name, c.email, c.company, c.role, c.status, c.date, c.amount])].map(row => row.map(v => '\"' + String(v).replace(/"'^[=+@-]/, "'"'"'$&").replaceAll('"'\"', '\"\"') + '\"').join(';')).join('\\r\\n');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8;' })); const a = document.createElement('a'); a.href = url; a.download = 'clients.csv'; a.click(); URL.revokeObjectURL(url); setToast("'`Экспортировано записей: ${exportRows.length}`);
  };
  const setStatus = (id: number, status: Status) => { setClients(prev => prev.map(c => c.id === id ? { ...c, status } : c)); setPopover(null); setDetail(null); setToast('"'Статус клиента обновлён'); };
