import {execFileSync} from 'node:child_process';
import fs from 'node:fs';
import crypto from 'node:crypto';
const names='libglib2.0-0 libnspr4 libnss3 libatk1.0-0 libatk-bridge2.0-0 libdbus-1-3 libcups2 libxkbcommon0 libasound2 libgbm1 libcairo2 libpango-1.0-0 libxcomposite1 libxdamage1 libxfixes3 libxrandr2 libatspi2.0-0 libdrm2 libwayland-server0 libpixman-1-0 libfontconfig1 libfreetype6 libxcb-shm0 libxcb-render0 libxrender1 libthai0 libharfbuzz0b libdatrie1 libgraphite2-3 libpng16-16'.split(' ');
const lines=execFileSync('apt-get',['--print-uris','download',...names],{encoding:'utf8'}).trim().split('\\n');
fs.mkdirSync('/tmp/kontur-libs',{recursive:true});
await Promise.all(lines.map(async line=>{
 const [,url,name,,hash]=line.match(/"'^'"'(["'^'"']+)' (\\S+) (\\d+) SHA256:(\\S+)/);
 const response=await fetch(url.replace('http:','https:')); if("'!response.ok)throw Error(response.status+url);
